from postprocess import own_case, observer_case, relative_comparison, exposure_comparison, stats, tsv, ORIGIN
from run_records import completed_output

ROOT=Path(__file__).resolve().parents[1]
FIELDS=('n','v','f_incident')


def sha(path):
    return hashlib.sha256(path.read_bytes()).hexdigest()


def experiment_identity(configs,case_root,left,right,allowed,expected,outer_prefix=False):
    """Check that a comparison changes only its registered experimental input."""
    reasons=[]
    if left not in configs or right not in configs:
        return dict(passed=False,reasons=['Both registered cases must complete'])
    ignored={'output_dir','threads','ct_radial_blocks','output_start_day','snapshot_days',
             'ecliptic_slice_pixels','ecliptic_extent_au','ecliptic_to_solar_matrix_csv','ecliptic_to_solar_matrix'}
    def equivalent(a,b,key):
        if key.endswith('_csv'):
            if a in (None,'') or b in (None,''):return a in (None,'') and b in (None,'')
            return a is not None and b is not None and Path(a).is_file() and Path(b).is_file() and sha(Path(a))==sha(Path(b))
        try:return float(a)==float(b)
        except (TypeError,ValueError):return a==b
    a,b=configs[left],configs[right]
    for name,cfg in [(left,a),(right,b)]:
        for key,value in expected.get(name,{}).items():
            actual=cfg.get(key,{'boundary_speed_offset_kms':'0'}.get(key))
            if not equivalent(actual,str(value),key):
                reasons.append(name+' has an unregistered '+key)
        for axis,count in [('r','nr'),('theta','ntheta'),('phi','nphi')]:
            center=np.load(case_root/name/(axis+('_au.npy' if axis=='r' else '_rad.npy')))
            face=np.load(case_root/name/(axis+'_faces_'+('au.npy' if axis=='r' else 'rad.npy')))
            n=int(cfg[count])
            if center.shape!=(n,) or face.shape!=(n+1,) or not np.all(np.isfinite(center)) or not np.all(np.isfinite(face)) or np.any(np.diff(face)<=0):
                reasons.append(name+' has invalid actual '+axis+' axes')
                continue
            bounds={'r':(float(cfg['rmin_au']),float(cfg['rmax_au'])),
                    'theta':(np.pi/2-np.deg2rad(float(cfg['latmax_deg'])),np.pi/2+np.deg2rad(float(cfg['latmax_deg']))),
                    'phi':(0,2*np.pi)}[axis]
            if not np.allclose(face,np.linspace(*bounds,n+1),rtol=0,atol=2e-13) or np.any(center<=face[:-1]) or np.any(center>=face[1:]):
                reasons.append(name+' actual '+axis+' geometry differs from its registered uniform grid')
    for key in set(a)|set(b):
        if key not in ignored and key not in allowed and not equivalent(a.get(key),b.get(key),key):
            reasons.append('Pair differs in unregistered '+key)
    for axis,parameters in [('r',{'nr','rmin_au','rmax_au'}),('theta',{'ntheta','latmax_deg'}),('phi',{'nphi'})]:
        if parameters.intersection(allowed):continue
        for suffix in [('_au.npy' if axis=='r' else '_rad.npy'),'_faces_'+('au.npy' if axis=='r' else 'rad.npy')]:
            x=np.load(case_root/left/(axis+suffix));y=np.load(case_root/right/(axis+suffix))
            if x.shape!=y.shape or not np.allclose(x,y,rtol=0,atol=2e-13):
                reasons.append('Unchanged '+axis+' axis differs between cases')
    if outer_prefix:
        for suffix in ['_au.npy','_faces_au.npy']:
            x=np.load(case_root/left/('r'+suffix));y=np.load(case_root/right/('r'+suffix))
            if len(x)<=len(y) or not np.allclose(x[:len(y)],y,rtol=0,atol=2e-13):
                reasons.append('Outer extension does not preserve the inner radial '+suffix)
    return dict(passed=not reasons,reasons=reasons,allowed_parameter_differences=sorted(allowed),
                registered_values=expected,native_axis_absolute_tolerance=2e-13,
                scope='Output-only flags and qualified decomposition may differ; all other physical/numerical settings are compared.')


def main():
    parser=argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--case-root',type=Path,default=ROOT/'results')
    parser.add_argument('--output',type=Path,default=ROOT/'validation/ct_convergence_summary.json')
    args=parser.parse_args()
    plan_path=ROOT/'validation/ct_convergence_plan.json'
    plan=json.loads(plan_path.read_text())
    gti=tsv(ROOT/'observations/xmm_gtis.tsv');gti=gti[gti['detector']=='pn']
    spans=list(zip(gti['start_mjd_utc']-ORIGIN,gti['stop_mjd_utc']-ORIGIN))
    frames={str(f):list(zip(gti[gti['frame']==f]['start_mjd_utc']-ORIGIN,gti[gti['frame']==f]['stop_mjd_utc']-ORIGIN)) for f in np.unique(gti['frame'])}
    cases={};sources={};excluded={};configs={}
    for folder in sorted(args.case_root.resolve().glob('ct*')):
        if not folder.is_dir():continue
        if not completed_output(folder):
            excluded[folder.name]='No completed statistics/probes or explicit incomplete controller marker'
            continue
        config=dict(line.split('=',1) for line in (folder/'run.cfg').read_text().splitlines() if '=' in line)
        trace=np.genfromtxt(folder/'ct_trace.csv',delimiter=',',names=True,ndmin=1)
        if len(trace)<2 or abs(trace['day'][0]-float(config['start_day']))>1e-10 or abs(trace['day'][-1]-float(config['end_day']))>1e-10 or np.any(np.diff(trace['day'])<=0):
            excluded[folder.name]='Native trace lacks monotonic configured endpoints'
