                av,bv=a.get(key),b.get(key)
                if key in ('boundary_map_csv','probes_csv'):
                    same=av is not None and bv is not None and sha(Path(av))==sha(Path(bv))
                else:
                    try:same=float(av)==float(bv)
                    except (TypeError,ValueError):same=av==bv
                if not same:reasons.append('Domain pair differs in '+key)
